# Source for q/ae-valve-aorta-ph2.js: Valve disease + Aorta + Pulmonary hypertension (second batch).
VD="Valve disease"; A="Aorta"; PH="Pulmonary hypertension"
Q=[
# --- Aortic stenosis ---
(VD,"Aortic sclerosis differs from aortic stenosis because sclerosis has:","Thickened or calcified cusps with a peak velocity under 2.5 m/s",["A peak velocity over 4 m/s","Fused commissures only","A valve area under 1.0 cm²"],"Sclerosis is common with aging and can progress to stenosis.","F"),
(VD,"Moderate aortic stenosis is usually defined by:","Peak velocity 3.0–3.9 m/s and mean gradient 20–39 mmHg",["Peak velocity 2.0–2.5 m/s","Mean gradient over 60 mmHg","Valve area over 2.0 cm²"],"Severe is 4.0 m/s or more and 40 mmHg or more.","F"),
(VD,"'Very severe' aortic stenosis is defined by:","Peak velocity of 5 m/s or more or mean gradient of 60 mmHg or more",["Peak velocity of 3 m/s","Mean gradient of 20 mmHg","Valve area of 1.5 cm²"],"Outcomes are poor even without symptoms.","F"),
(VD,"Stage D3 aortic stenosis (paradoxical low-flow, low-gradient) has:","Valve area of 1.0 cm² or less, mean gradient under 40 mmHg, normal EF and stroke volume index under 35 mL/m²",["Reduced EF with low gradient","High gradient with normal flow","Mild AS"],"It is common in older patients with small, thick LVs.","C"),
(VD,"When AS severity measures disagree, CT aortic valve calcium scoring suggests severe AS at about:","2,000 AU or more in men and 1,200 AU or more in women",["100 AU in both","10,000 AU in both","500 AU in men only"],"Women develop severe AS with less calcium.","C"),
(VD,"Rapid progression of aortic stenosis is suggested by an increase in peak velocity of:","0.3 m/s or more per year",["0.01 m/s per year","No change","Any change at all"],"Rapid progression may lead to earlier valve replacement.","C"),
(VD,"Valve replacement is generally recommended in severe AS when:","The patient has symptoms, or the EF falls under 50%",["The patient is asymptomatic with normal EF always","The valve area is 1.8 cm²","Mild AR is present"],"Exercise testing can reveal hidden symptoms.","F"),
(VD,"Heyde syndrome is the link between aortic stenosis and:","Gastrointestinal bleeding from angiodysplasia",["Stroke","Kidney stones","Hearing loss"],"High shear stress breaks down von Willebrand factor.","C"),
# --- Aortic regurgitation ---
(VD,"An AR regurgitant volume of 60 mL or more per beat suggests:","Severe AR",["Mild AR","Moderate AR","No AR"],"Severe AR also has an EROA of 0.3 cm² or more.","F"),
(VD,"Surgery for asymptomatic chronic severe AR is often recommended when the LV end-systolic diameter exceeds about:","50 mm (or 25 mm/m²)",["30 mm","20 mm","70 mm only"],"An EF of 55% or less is another trigger.","C"),
(VD,"A central AR jet with normal cusps is most often caused by:","A dilated aortic root or annulus",["Cusp prolapse","Endocarditis perforation","Bicuspid valve always"],"Eccentric jets suggest cusp problems such as prolapse.","F"),
(VD,"Acute severe AR is often hard to see because:","The LV is not dilated and LV pressure rises quickly, making the jet short and brief",["The jet is always huge","It never causes symptoms","It only occurs in children"],"A very short PHT and early mitral closure are clues.","C"),
# --- Mitral regurgitation ---
(VD,"Carpentier type II mitral dysfunction means:","Excessive leaflet motion (prolapse or flail)",["Normal leaflet motion","Restricted motion in systole and diastole","Restricted motion in systole only"],"Type I is normal motion (e.g. perforation or annular dilation); type IIIa is rheumatic; type IIIb is ischemic or functional.","F"),
(VD,"Carpentier type IIIa mitral dysfunction (restricted in both systole and diastole) is typical of:","Rheumatic disease",["Ischemic MR","Flail leaflet","Annular dilation only"],"Thick leaflets and fused commissures limit opening and closing.","C"),
(VD,"Barlow disease differs from fibroelastic deficiency because Barlow valves are:","Large, thick and redundant, often with multi-scallop prolapse",["Thin with a single ruptured chord","Calcified and stenotic","Normal"],"Fibroelastic deficiency usually affects older patients with a single flail segment.","C"),
(VD,"A mitral E velocity over about 1.2 m/s in a patient with MR (and no MS) suggests:","Severe MR",["Mild MR","Mitral stenosis","Normal filling"],"Large regurgitant volume increases forward diastolic flow.","C"),
(VD,"In chronic severe primary MR, surgery is recommended for asymptomatic patients when:","EF is 60% or less or LV end-systolic diameter is 40 mm or more",["EF is over 70%","LV size is normal","There is mild TR"],"Repair is preferred over replacement when feasible.","C"),
(VD,"Atrial functional MR is mainly caused by:","Atrial fibrillation with LA and annular enlargement, with normal leaflets and LV",["Rheumatic disease","Endocarditis","Papillary muscle rupture"],"Rhythm control may reduce it.","C"),
(VD,"A regurgitant volume of 60 mL or more for primary MR is graded as:","Severe",["Mild","Moderate","Trivial"],"A regurgitant fraction of 50% or more is also severe.","F"),
# --- MS, tricuspid, pulmonic ---
(VD,"Before balloon mitral valvuloplasty, TEE is important mainly to:","Exclude LA or LAA thrombus and check MR severity",["Measure the aortic root","Measure LV mass","Look at the pulmonic valve"],"More than moderate MR is also a reason not to proceed.","F"),
(VD,"Lutembacher syndrome is the combination of:","Atrial septal defect and mitral stenosis",["VSD and AS","PDA and coarctation","TOF and AR"],"The ASD lets the LA decompress, so the MS gradient may underestimate severity.","C"),
(VD,"Severe tricuspid stenosis is suggested by a mean gradient of:","5 mmHg or more",["1 mmHg","20 mmHg only","Any gradient"],"It is often rheumatic and appears with mitral disease.","C"),
(VD,"In severe TR, the CW Doppler signal often looks:","Dense and triangular, peaking early (a 'V-wave cutoff')",["Faint and rounded","Absent","Diastolic only"],"Rapid equalization of RV and RA pressure produces the early peak.","F"),
(VD,"Newer TR grading adds which grades beyond severe?","Massive and torrential",["Trace and trivial","Minimal and mild","Stage A and B only"],"These grades help select patients for transcatheter therapies.","C"),
(VD,"At left-sided valve surgery, tricuspid repair is often considered if the tricuspid annulus is at least:","40 mm (or 21 mm/m²) in diastole",["20 mm","30 mm in systole","60 mm only"],"A dilated annulus predicts TR progression.","C"),
(VD,"Severe pulmonic stenosis is suggested by a peak velocity of more than:","4 m/s (peak gradient over 64 mmHg)",["1 m/s","2 m/s","3 m/s only"],"Mild PS has a peak velocity under 3 m/s.","F"),
(VD,"A thickened, dysplastic pulmonic valve that does not dome is associated with:","Noonan syndrome",["Marfan syndrome","Down syndrome","Kawasaki disease"],"Dysplastic valves respond poorly to balloon valvuloplasty.","C"),
(VD,"Severe pulmonic regurgitation typically shows:","A dense PR signal with a steep slope ending early in diastole (PHT under about 100 ms)",["A faint signal lasting all of diastole","No signal","A signal only in systole"],"Pressures in the PA and RV equalize quickly.","C"),
(VD,"Ergot drugs and fenfluramine can cause a valve disease that looks like:","Carcinoid valve disease (thick, stiff, retracted leaflets)",["Mitral prolapse","Bicuspid aortic valve","Ebstein anomaly"],"Unlike carcinoid, they often affect left-sided valves.","C"),
(VD,"Libman–Sacks endocarditis (in lupus) is:","Non-infective, wart-like lesions, often on the mitral valve",["A bacterial infection","A tumor","A congenital defect"],"It may be linked with antiphospholipid antibodies.","F"),
(VD,"Rheumatic mitral disease also commonly involves the:","Chordae, which become thickened, shortened and fused",["Pulmonary veins","Coronary arteries","Pericardium only"],"Subvalvular disease affects suitability for balloon valvuloplasty.","F"),
# --- Aorta ---
(A,"Elective surgery for an ascending aortic aneurysm in most adults is usually recommended at a diameter of about:","5.5 cm",["3.5 cm","4.0 cm","7.5 cm"],"Lower thresholds apply in Marfan syndrome and some other conditions.","F"),
(A,"In Marfan syndrome, the aortic root typically becomes 'pear-shaped' because of:","Loss of the sinotubular junction (effacement)",["Narrowing of the sinuses","Coarctation","Calcification"],"The dilation is greatest at the sinuses of Valsalva.","F"),
(A,"An abdominal aortic aneurysm is defined by a diameter of:","3.0 cm or more",["1.5 cm","2.0 cm","6.0 cm only"],"Repair is often advised at about 5.5 cm in men.","F"),
(A,"A reverberation artifact in the ascending aorta can mimic a dissection flap. Clues that it is an artifact include:","It moves parallel with the aortic walls, crosses anatomic borders, and color flow passes through it",["It moves independently with a tear","It separates true and false lumens","It has an entry tear"],"Check from more than one view.","C"),
(A,"Stanford type B aortic dissection is usually treated with:","Medical therapy (blood pressure and heart rate control), with stenting if complicated",["Emergency open surgery always","No treatment","Valve replacement"],"Type A dissection usually needs emergency surgery.","F"),
(A,"The most important risk factor for aortic dissection is:","High blood pressure",["Low cholesterol","Asthma","Diabetes only"],"Connective tissue disease, bicuspid valves and cocaine are other risks.","F"),
(A,"A pericardial effusion in a patient with type A dissection suggests:","Possible rupture into the pericardium, an emergency",["A benign finding","Pericarditis only","Normal finding"],"It can quickly lead to tamponade.","F"),
(A,"Turner syndrome is associated with:","Coarctation of the aorta and bicuspid aortic valve",["Mitral stenosis","Tetralogy of Fallot","Ebstein anomaly"],"Women with Turner syndrome are at risk of dissection.","F"),
(A,"Traumatic aortic injury after deceleration usually occurs at the:","Isthmus, just beyond the left subclavian artery",["Aortic root","Abdominal aorta","Celiac artery"],"This is where the mobile arch meets the fixed descending aorta.","C"),
(A,"Takayasu arteritis typically affects:","Young women, causing thickening and narrowing of the aorta and its branches",["Elderly men only","Infants only","Only the coronary arteries"],"It can cause aortic regurgitation if the root is involved.","C"),
(A,"Syphilitic aortitis classically involves the:","Ascending aorta, with aneurysm and aortic regurgitation",["Abdominal aorta only","Pulmonary artery","Coronary sinus"],"The aortic wall may show a 'tree-bark' appearance.","C"),
(A,"A right aortic arch can be recognized from the suprasternal view when:","The arch runs to the right of the trachea and the first branch goes to the left",["The first branch goes to the right","The arch is normal","There is no arch"],"It is associated with tetralogy of Fallot and other defects.","C"),
(A,"Rib notching on chest X-ray in coarctation is caused by:","Enlarged intercostal collateral arteries",["Broken ribs","Enlarged pulmonary veins","Pericardial fluid"],"Collaterals carry blood around the narrowing.","F"),
(A,"After coarctation repair, the main echo follow-up concern is:","Recoarctation, aneurysm at the repair site, and bicuspid valve disease",["Mitral stenosis","Pulmonary hypertension only","Atrial septal defect"],"Persistent hypertension is also common.","F"),
(A,"In vascular Ehlers–Danlos syndrome, the main risk is:","Spontaneous rupture of arteries and organs",["Coronary calcification","Aortic stenosis","Mitral stenosis"],"Patients need careful vascular imaging.","C"),
(A,"Annuloaortic ectasia means:","Dilation of the aortic annulus, sinuses and proximal ascending aorta",["Narrowing of the annulus","Dilation of the abdominal aorta only","Aortic valve stenosis"],"It often causes central aortic regurgitation.","F"),
# --- Pulmonary hypertension ---
(PH,"The 2022 ESC/ERS definition of pulmonary hypertension is a mean PA pressure at rest of:","More than 20 mmHg",["More than 40 mmHg","More than 10 mmHg","More than 60 mmHg"],"It is measured by right heart catheterization.","F"),
(PH,"Pre-capillary pulmonary hypertension is defined by a PA wedge pressure of:","15 mmHg or less with PVR over 2 Wood units",["Over 15 mmHg","Over 30 mmHg","Any value"],"Post-capillary PH (group 2) has a wedge pressure over 15 mmHg.","C"),
(PH,"A TR velocity of 2.8 m/s or less with no other PH signs suggests:","Low echo probability of pulmonary hypertension",["High probability","Intermediate probability","Confirmed PH"],"2.9–3.4 m/s is intermediate; over 3.4 m/s is high.","F"),
(PH,"WHO group 2 pulmonary hypertension is caused by:","Left heart disease",["Lung disease","Chronic blood clots","Idiopathic PAH"],"This is the most common group (raised LA pressure).","F"),
(PH,"WHO group 5 pulmonary hypertension includes:","Conditions with unclear or multiple causes, such as sarcoidosis or sickle cell disease",["Left heart failure","COPD","CTEPH"],"The cause is often a mix of several mechanisms.","C"),
(PH,"Chronic thromboembolic pulmonary hypertension (CTEPH) is best screened for with:","A V/Q lung scan",["An echo alone","An ECG","A chest X-ray only"],"It may be cured with pulmonary endarterectomy.","C"),
(PH,"Which drug use is linked to pulmonary arterial hypertension (group 1)?","Methamphetamine",["Aspirin","Vitamin D","Penicillin"],"Some appetite-suppressant drugs are also linked.","C"),
(PH,"Schistosomiasis is an important cause of pulmonary arterial hypertension in:","Regions where the parasite is common",["Only in Arctic regions","Only in children with Kawasaki","Nowhere"],"It is a leading cause of PAH worldwide.","C"),
(PH,"Eisenmenger syndrome occurs when:","A long-standing left-to-right shunt causes severe PH and the shunt reverses to right-to-left",["A shunt closes on its own","LV hypertrophy develops","The aortic valve calcifies"],"Patients become cyanotic. Closing the defect is then contraindicated.","F"),
(PH,"RV pressure overload differs from RV volume overload on echo because pressure overload causes:","Septal flattening mostly in systole",["Septal flattening only in diastole","No septal change","LV dilation"],"Volume overload flattens the septum mainly in diastole.","F"),
(PH,"A PA-to-aorta diameter ratio over 1 suggests:","Pulmonary hypertension",["Normal anatomy","Aortic aneurysm only","Coarctation"],"The main PA is normally smaller than the aorta.","F"),
(PH,"In high-risk acute PE with shock, the usual treatment is:","Clot-dissolving therapy (thrombolysis) or clot removal",["Watchful waiting","Antibiotics","Beta-blockers"],"Echo showing RV failure supports urgent treatment.","F"),
(PH,"Pulmonary vein stenosis can occur after:","Catheter ablation for atrial fibrillation",["Aortic valve replacement","PFO closure","Pacemaker insertion"],"It causes high-velocity, turbulent flow in the vein.","C"),
(PH,"In PAH, a TAPSE/PASP ratio under about 0.55 mm/mmHg suggests:","Poor RV–pulmonary artery coupling and worse prognosis",["Normal coupling","Mild disease only","LV failure"],"It reflects how well the RV copes with its afterload.","C"),
(PH,"Pulmonary hypertension at high altitude is caused mainly by:","Low oxygen causing pulmonary artery constriction",["Valve disease","Coronary disease","Pericarditis"],"It falls in WHO group 3.","F"),
(PH,"Which RV finding suggests chronic rather than acute pressure overload?","RV free wall thickness over 5 mm (hypertrophy)",["A thin RV wall","A normal RV","A small RA"],"In acute PE, the RV dilates but has not had time to thicken.","F"),
(PH,"In group 2 PH from left heart disease, which echo finding is typical?","A large LA and signs of raised LV filling pressure",["A small LA","Normal E/e′","Normal LV and LA"],"Treating the left heart condition is the priority.","F"),
]
